/* 生成规范化的 PAPERS 数组（与旧数据结构兼容） */
const PAPERS = PAPERS_RAW.map((r, i) => ({
  id: "p" + String(i + 1).padStart(3, "0"),
  title: r[0],
  authors: r[1],
  venue: r[2],
  year: r[3],
  tags: r[4],
  summary: r[5],
  url: r[6] || "",
}));

/* 2025 / 2026 年新论文优先展示（稳定排序：新论文按年份倒置，其余保持原分类顺序） */
PAPERS.sort((a, b) => {
  const an = a.year >= 2025 ? 1 : 0;
  const bn = b.year >= 2025 ? 1 : 0;
  if (an !== bn) return bn - an;
  if (an && bn && a.year !== b.year) return b.year - a.year;
  return 0;
});
